			offSet = i * MAX_ENCRYPT_BLOCK;
		}
		byte[] encryptedData = out.toByteArray();
		out.close();
		return encryptedData;
	}

	/**
	 * <p>
	 * 私钥加密
	 * </p>
	 * 
	 * @param data
	 *            源数据
	 * @param privateKey
	 *            私钥(BASE64编码)
	 * @return
	 * @throws Exception
	 */
	public static byte[] encryptByPrivateKey(byte[] data, String privateKey)
			throws Exception {
		byte[] keyBytes = Base64.decode(privateKey);
		PKCS8EncodedKeySpec pkcs8KeySpec = new PKCS8EncodedKeySpec(keyBytes);
		KeyFactory keyFactory = KeyFactory.getInstance(KEY_ALGORITHM);
		Key privateK = keyFactory.generatePrivate(pkcs8KeySpec);
		Cipher cipher = Cipher.getInstance(keyFactory.getAlgorithm());
		cipher.init(Cipher.ENCRYPT_MODE, privateK);
		int inputLen = data.length;
		ByteArrayOutputStream out = new ByteArrayOutputStream();
		int offSet = 0;
		byte[] cache;
		int i = 0;
		// 对数据分段加密
		while (inputLen - offSet > 0) {
			if (inputLen - offSet > MAX_ENCRYPT_BLOCK) {
				cache = cipher.doFinal(data, offSet, MAX_ENCRYPT_BLOCK);
			} else {
				cache = cipher.doFinal(data, offSet, inputLen - offSet);
			}
			out.write(cache, 0, cache.length);
			i++;
			offSet = i * MAX_ENCRYPT_BLOCK;
		}
		byte[] encryptedData = out.toByteArray();
		out.close();
		return encryptedData;
	}

	/**
	 * <p>
	 * 获取私钥
	 * </p>
	 * 
	 * @param keyMap
	 *            密钥对
	 * @return
	 * @throws Exception
	 */
	public static String getPrivateKey(Map<String, Object> keyMap)
			throws Exception {
		Key key = (Key) keyMap.get(PRIVATE_KEY);
		return Base64.encode(key.getEncoded());
	}

	/**
	 * <p>
	 * 获取公钥
	 * </p>
	 * 
	 * @param keyMap
	 *            密钥对
	 * @return
	 * @throws Exception
	 */
	public static String getPublicKey(Map<String, Object> keyMap)
			throws Exception {
		Key key = (Key) keyMap.get(PUBLIC_KEY);
		return Base64.encode(key.getEncoded());
	}

	public static void main(String[] args) {
		try {
            Map<String, Object> keyMap = genKeyPair();
            String publicKey = getPublicKey(keyMap);
            String privateKey = getPrivateKey(keyMap);
            System.err.println("公钥: \n\r" + publicKey);
            System.err.println("私钥： \n\r" + privateKey);



            System.err.println("公钥加密——私钥解密");
            String source = "这是一行没有任何意义的文字，你看完了等于没看，不是吗？";
            System.out.println("\r加密前文字：\r\n" + source);
            byte[] data = source.getBytes();
            byte[] encodedData = encryptByPublicKey(data, publicKey);
            System.out.println("加密后文字：\r\n" + new String(encodedData));
            byte[] decodedData = decryptByPrivateKey(encodedData, privateKey);
            String target = new String(decodedData);
            System.out.println("解密后文字: \r\n" + target);

            System.err.println("私钥加密——公钥解密");
            String source2 = "这是一行测试RSA数字签名的无意义文字";
            System.out.println("原文字：\r\n" + source2);
            byte[] data2 = source2.getBytes();
            byte[] encodedData2 = encryptByPrivateKey(data2, privateKey);
            System.out.println("加密后：\r\n" + new String(encodedData2));
            byte[] decodedData2 = decryptByPublicKey(encodedData2, publicKey);
            String target2 = new String(decodedData2);
            System.out.println("解密后: \r\n" + target2);
            System.err.println("私钥签名——公钥验证签名");
            String sign2 = sign(encodedData2, privateKey);
            System.err.println("签名:\r" + sign2);
            boolean status = verify(encodedData2, publicKey, sign2);
            System.err.println("验证结果:\r" + status);

        } catch (Exception e) {
            e.printStackTrace();
        }
	}

}

