HostnameVerifier hostnameVerifier = new HostnameVerifier() {
    @Override
    public boolean verify(String hostname, SSLSession session) {
        try {
            java.security.cert.Certificate[] certs = session.getPeerCertificates();
            if (certs != null && certs.length > 0 && certs[0] instanceof java.security.cert.X509Certificate) {
                java.security.cert.X509Certificate x509 = (java.security.cert.X509Certificate) certs[0];
                x509.checkValidity();
                String cn = getCommonName(x509);
                return hostname != null && hostname.equalsIgnoreCase(cn);
            }
        } catch (Exception e) {
            logger.warn("hostname verification failed", e);
        }
        return false;
    }

    private String getCommonName(java.security.cert.X509Certificate cert) {
        String dn = cert.getSubjectX500Principal().getName();
        for (String part : dn.split(",")) {
            String trimmed = part.trim();
            if (trimmed.startsWith("CN=")) {
                return trimmed.substring(3).trim();
            }
        }
        return "";
    }
};

