				Inimigo1 in = inimigo1.get(o);
				in.load();
				graficos.drawImage(in.getImagem(), in.getX(), in.getY(), this);
			} // for

			for (int y = 0; y < inimigo2.size(); y++) {
				Inimigo2 pn = inimigo2.get(y);
