		else {
			ImageIcon fimJogo = new ImageIcon("res\\fimdejogo.png");
			graficos.drawImage(fimJogo.getImage(), 0, 0, 1024, 728, null);
		} // else

		g.dispose();

	}// paint

	@Override
	public void actionPerformed(ActionEvent e) {
		player.update();

		if (player.isTurbo()) {
			timer.setDelay(1);
			player.setTurboLiberar(player.getTurboLiberar() - 1);
		}

		if (player.isTurbo() == false) {
			timer.setDelay(20);
		}

		if (contNivel2 == 0 && contInim1 == 10) { // nivel 2
			this.setIni2(this.getIni2() + 20);

			// Inimigo1.setVELOCIDADE(Inimigo1.getVELOCIDADE() + 1);

			this.inicializaInimigos2();

			contNivel2++;
		}

		if (contNivel3 == 0 && contInim2 == 10) { // nivel 2
			this.setIni3(this.getIni3() + 20);

