		}else if(command.equals("updateScoreCommu")) {

			int cmb_no = Integer.parseInt(request.getParameter("cmb_no"));

			//회원 현재 점수
			int score = memdto.getMb_score();
			//업데이트 할 점수
			int scoreUpdate = score + 1;
			System.out.println("업데이트할 점수: " + scoreUpdate + "회원 점수: " + score);

