package net.segoia.util.net.nio;

public class RspHandler {
    private byte[] rsp = null;

    public synchronized boolean handleResponse(byte[] rsp) {
	this.rsp = rsp;
	this.notify();
	return true;
    }

    public String getResponseAsString() {
	return (new String(getResponse()));
