						+ trans[2]*trans[3]*trans[7]
						- (1+trans[0])*trans[5]*trans[7]
						- trans[2]*(1+trans[4])*trans[6]
						- trans[1]*trans[3]*(1+trans[8]);
		}
		return scaling;
	}

