package com.servicio.reparaciones.servicio;

import com.servicio.reparaciones.modelo.nosql.Articulo;
import com.servicio.reparaciones.modelo.nosql.Bodega;
import com.servicio.reparaciones.modelo.nosql.Inventario;
import com.servicio.reparaciones.modelo.nosql.Salida;
import com.servicio.reparaciones.servicio.I.Isalida;
import com.servicio.reparaciones.servicio.util.Calendario;
import com.servicio.reparaciones.util.MongoPersistence;
import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;
import javax.ejb.LocalBean;
import javax.ejb.Stateless;
import javax.inject.Inject;
import org.mongodb.morphia.Datastore;
import org.mongodb.morphia.query.Query;
import org.mongodb.morphia.query.UpdateOperations;
import org.mongodb.morphia.query.UpdateResults;

/**
 *
 * @author luis
 */
@Stateless
@LocalBean
public class SalidaService implements Isalida, Serializable {

    private static final long serialVersionUID = -7588891280802943350L;
    private MongoPersistence conn = new MongoPersistence();
    private Datastore ds = conn.context();
    private Calendario calendario = new Calendario();

    @Inject
    private InventarioService inventarioService;

    @Override
    public Integer generatedCodigo() {
        Integer size = ObtenerListaSalidas().size();
        Integer code = 1000 + 1 * size;
        return code;
    }

    @Override
    public Boolean insert(Salida salida) {
        Boolean exito = Boolean.FALSE;
        if (salida != null) {
            salida.setCodigo(generatedCodigo());
            salida.setFlag(1);
            this.ds.save(salida);
            this.inventarioService.insert(new Inventario(salida.getCode(),
                    salida.getCantidad() * salida.getSigno(),
                    salida.getBodega(),
                    salida.getArticulo()));
            exito = Boolean.TRUE;
        }
        return exito;
    }

    @Override
    public Boolean update(Salida salida) {
        Query<Salida> query = this.ds.createQuery(Salida.class);
        query.and(
                query.criteria("codigo").equal(salida.getCodigo())
        );
        UpdateOperations<Salida> update = this.ds.createUpdateOperations(Salida.class);
        update.set("signo", salida.getSigno()).
                set("concepto", salida.getConcepto()).
                set("cantidad", salida.getCantidad()).
                set("precioUnit", salida.getPrecioUnit()).
                set("precioTotal", salida.getPrecioTotal()).
                set("articulo", salida.getArticulo()).
                set("bodega", salida.getBodega()).
                set("quienRecibe", salida.getQuienRecibe()).
                set("username", salida.getUsername()).
                set("lastChange", this.calendario.getCalendario().getTime()).
                set("flag", salida.getFlag());
        UpdateResults results = this.ds.update(query, update);
        Inventario in = this.inventarioService.findByCodigo(salida.getCode());
        in.setBodega(salida.getBodega());
        in.setArticulo(salida.getArticulo());
        in.setCantidad(salida.getCantidad() * salida.getSigno());
        this.inventarioService.update(in);
        return results.getUpdatedExisting();
    }

    @Override
    public Salida findByCodigo(Salida salida) {
        Salida find = new Salida();
        Query<Salida> result = this.ds.find(Salida.class).
                field("codigo").equal(salida.getCodigo()).
                field("flag").equal(1);
        if (result.asList() != null && !result.asList().isEmpty()) {
            find = result.asList().get(0);
        }
        return find;
    }

    public Salida findByConcepto(Salida salida) {
        Salida find = new Salida();
        Query<Salida> result = this.ds.find(Salida.class).
                field("concepto").equal(salida.getConcepto()).
                field("flag").equal(1);
        if (result.asList() != null && !result.asList().isEmpty()) {
            find = result.asList().get(0);
        }
        return find;
    }

    public List<Salida> findByBodegaArticulo(Bodega bodega, Articulo articulo) {
        List<Salida> find = new ArrayList<>();
        Query<Salida> result = this.ds.find(Salida.class).
                field("articulo").equal(articulo).
                field("bodega").equal(bodega).
                field("flag").equal(1);
        if (result.asList() != null && !result.asList().isEmpty()) {
            find = result.asList();
        }
        return find;
    }

    @Override
    public void delete(Salida salida) {
        this.delete(salida);
    }

    @Override
    public Boolean deleteFlag(Salida salida) {
        salida.setFlag(0);
        Query<Salida> query = this.ds.createQuery(Salida.class);
        query.and(
                query.criteria("codigo").equal(salida.getCodigo())
        );
        UpdateOperations<Salida> update = this.ds.createUpdateOperations(Salida.class);
        update.set("flag", salida.getFlag());
        UpdateResults results = this.ds.update(query, update);
        Inventario in = this.inventarioService.findByCodigo(salida.getCode());
        in.setBodega(salida.getBodega());
        in.setArticulo(salida.getArticulo());
        in.setCantidad(salida.getCantidad() * salida.getSigno());
        this.inventarioService.update(in);
        return results.getUpdatedExisting();
    }

    @Override
    public List<Salida> ObtenerListaSalidas(Integer flag) {
        List<Salida> list = new ArrayList<>();
        Query<Salida> result = this.ds.find(Salida.class).
                field("flag").equal(flag);
        if (result.asList() != null && !result.asList().isEmpty()) {
            list = result.asList();
        }
        if (list == null) {
            list = new ArrayList<>();
        }
        return list;
    }

    public List<Salida> ObtenerListaSalidas() {
        List<Salida> list = new ArrayList<>();
        Query<Salida> result = this.ds.find(Salida.class);
        if (result.asList() != null && !result.asList().isEmpty()) {
            list = result.asList();
        }
        if (list == null) {
            list = new ArrayList<>();
        }
        return list;
    }

}

package com.macphail.adventures.business.game.service;


import com.macphail.adventures.business.game.api.AdventureApi;
import com.macphail.adventures.business.game.model.adventure.Adventure;
import com.macphail.adventures.business.game.model.adventure.Player;
import com.macphail.adventures.business.game.model.adventure.exceptions.PlayerNotInAdventureException;
import com.macphail.adventures.business.game.model.event.DomainEventPublisher;
import com.macphail.adventures.business.game.repository.AdventureRepository;

import javax.ejb.Stateless;
import javax.inject.Inject;
import java.io.Serializable;

@Stateless
public class AdventureService implements AdventureApi, Serializable {

    @Inject
    private AdventureRepository adventureRepository;

    @Inject
    DomainEventPublisher eventPublisher;

    @Override
    public void playerJoinsAdventure(long adventureId, String userId, String playerName, String playerDescription) {
        Adventure adventure = findAdventure(adventureId);

        Player.joinAdventure(userId, adventure, playerName, playerDescription);
    }

    @Override
    public void gameMasterWritesNarrative(long adventureId, String content) {
        Adventure adventure = findAdventure(adventureId);

        adventure.getGameMaster().writeNarrative(content);
    }

    @Override
    public void playersReact(long adventureId, long playerId, String content) {
        Player player = findPlayer(adventureId, playerId);

        player.react(content);
    }

    @Override
    public void progressAdventure(long adventureId, String description) {
        Adventure adventure = findAdventure(adventureId);

        adventure.getGameMaster().progressReached(description);
    }

    @Override
    public void playerDoesHeroicDeed(long adventureId, long playerId, String description) {
        Player player = findPlayer(adventureId, playerId);

        player.doHeroicDeeds(description);
    }

    @Override
    public void gameMasterCancelsAdventure(long adventureId) {
        Adventure adventure = findAdventure(adventureId);
        adventure.getGameMaster().cancelAdventure();
    }

    @Override
    public void playerLeavesAdventure(long adventureId, long playerId) {
        Player player = findPlayer(adventureId, playerId);
        player.leaveAdventure();
    }

    private Adventure findAdventure(long adventureId) {
        Adventure adventure = adventureRepository.findById(adventureId);
        adventure.setDomainEventPublisher(eventPublisher);
        return adventure;
    }

    private Player findPlayer(long adventureId, long playerId) {
        Adventure adventure = findAdventure(adventureId);

        return adventure.playerFor(playerId)
                .orElseThrow(PlayerNotInAdventureException::new);
    }
}

package edu.harvard.iq.dataverse.search;

import edu.harvard.iq.dataverse.DvObject;
import edu.harvard.iq.dataverse.DvObjectServiceBean;
import edu.harvard.iq.dataverse.IndexServiceBean;
import edu.harvard.iq.dataverse.util.SystemConfig;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.logging.Logger;
import javax.ejb.EJB;
import javax.ejb.Stateless;
import javax.inject.Named;
import org.apache.solr.client.solrj.SolrServer;
import org.apache.solr.client.solrj.SolrServerException;
import org.apache.solr.client.solrj.impl.HttpSolrServer;
import org.apache.solr.client.solrj.response.UpdateResponse;
import org.apache.solr.common.SolrInputDocument;

@Named
@Stateless
public class SolrIndexServiceBean {

    private static final Logger logger = Logger.getLogger(SolrIndexServiceBean.class.getCanonicalName());

    @EJB
    SystemConfig systemConfig;
    @EJB
    DvObjectServiceBean dvObjectServiceBean;
    @EJB
    SearchPermissionsServiceBean searchPermissionsService;
    @EJB
    SearchDebugServiceBean searchDebugService;

    public IndexResponse indexAllPermissions() {
        Collection<SolrInputDocument> docs = new ArrayList<>();

        List<DvObjectSolrDoc> definitionPoints = new ArrayList<>();
        for (DvObject dvObject : dvObjectServiceBean.findAll()) {
            definitionPoints.addAll(searchDebugService.determineSolrDocs(dvObject.getId()));
        }

        for (DvObjectSolrDoc dvObjectSolrDoc : definitionPoints) {
            SolrInputDocument solrInputDocument = createSolrDoc(dvObjectSolrDoc);
            docs.add(solrInputDocument);
        }
        try {
            persistToSolr(docs);
            /**
             * @todo Do we need a separate permissionIndexTime timestamp?
             * Probably. Update it here.
             */
            return new IndexResponse("indexed all permissions");
        } catch (SolrServerException | IOException ex) {
            return new IndexResponse("problem indexing");
        }

    }

    public IndexResponse indexPermissionsForOneDvObject(long dvObjectId) {
        Collection<SolrInputDocument> docs = new ArrayList<>();

        List<DvObjectSolrDoc> definitionPoints = searchDebugService.determineSolrDocs(dvObjectId);

        for (DvObjectSolrDoc dvObjectSolrDoc : definitionPoints) {
            SolrInputDocument solrInputDocument = createSolrDoc(dvObjectSolrDoc);
            docs.add(solrInputDocument);
        }
        try {
            persistToSolr(docs);
            /**
             * @todo Do we need a separate permissionIndexTime timestamp?
             * Probably. Update it here.
             */
            return new IndexResponse("attempted to index permissions for DvObject " + dvObjectId);
        } catch (SolrServerException | IOException ex) {
            return new IndexResponse("problem indexing");
        }

    }

    private SolrInputDocument createSolrDoc(DvObjectSolrDoc dvObjectSolrDoc) {
        SolrInputDocument solrInputDocument = new SolrInputDocument();
        solrInputDocument.addField(SearchFields.ID, dvObjectSolrDoc.getSolrId() + IndexServiceBean.discoverabilityPermissionSuffix);
        solrInputDocument.addField(SearchFields.DEFINITION_POINT, dvObjectSolrDoc.getSolrId());
        solrInputDocument.addField(SearchFields.DISCOVERABLE_BY, dvObjectSolrDoc.getPermissions());
        return solrInputDocument;
    }

    private void persistToSolr(Collection<SolrInputDocument> docs) throws SolrServerException, IOException {
        if (docs.isEmpty()) {
            /**
             * @todo Throw an exception here? "DvObject id 9999 does not exist."
             */
            return;
        }
        SolrServer solrServer = new HttpSolrServer("http://" + systemConfig.getSolrHostColonPort() + "/solr");
        /**
         * @todo Do something with these responses from Solr.
         */
        UpdateResponse addResponse = solrServer.add(docs);
        UpdateResponse commitResponse = solrServer.commit();
    }
}

