        }
    }

    private void closeDbConnection() throws SauronException {
        try {
            this.connectionSource.close();
        } catch (IOException e) {
            LOGGER.warn(e.getCause().getMessage());
            throw new SauronException(Utilities.getResourceBundle().getString("error.get.dao"));
