		Boolean estaValidado=false;

		if(tipoinven.getIsNew() || tipoinven.getIsChanged()) { 
			this.invalidValues = tipoinvenValidator.getInvalidValues(tipoinven);

			if(this.invalidValues==null || this.invalidValues.length<=0) {
