        if (interrupted) {
            Thread.currentThread().interrupt();
        }
    }

    private synchronized void yield() {
        boolean interrupted = false;
        try {
            wait(this.devicePeriod);
        } catch (InterruptedException e) {
            interrupted = true;
        }
        if (interrupted) {
            Thread.currentThread().interrupt();
        }
    }
}

