                "IF EXISTS ("
                + "SELECT id FROM question_answer "
                + "WHERE id = '"+id+"') "
                + "DELETE FROM question_answer WHERE id = '"+id+"';"
                        + "SELECT id FROM question_answer WHERE id='1';");
    }

}

