package database;
import java.sql.*;

/**
 * Manages the MySQL database connection and queries.
 * @author <NAME>
 */
public class DatabaseManager {
    private static Connection conn = null;

    /**
     * Initializes the connection.
     * @param location The port.
     */
    public static void Init(String location) {
        try {
            Class.forName("com.mysql.cj.jdbc.Driver");
        }
        catch (ClassNotFoundException e) {
            System.out.println(e.getMessage());
        }

        for (int i = 0; i < 50; ++i) {
            try  {
                Thread.sleep(30000);
                String temp = String.format("jdbc:mysql://%s/world?allowPublicKeyRetrieval=true&useSSL=false", location);
                conn = DriverManager.getConnection(temp, "root", "group25");
                break;
            }
            catch (Exception e) {
                System.out.println(e.getMessage());
            }
        }
    }

    /**
     * Deinitializes the connection.
     */
    public static void DeInit() {
        if (conn != null) {
            try {
                conn.close();
            }
            catch (Exception e) {
                System.out.println(e.getMessage());
            }
        }
    }

    /**
     * Execute a query.
     * @param query The MySQL query to run.
     * @return {@link ResultSet} of the query.
     */
    public static ResultSet Execute(final String query) {
        ResultSet result_set = null;

        try {
            Statement statement = conn.createStatement();
            result_set = statement.executeQuery(query);
        }
        catch (SQLException e) {
            System.out.println(e.getMessage());
        }

        return result_set;
    }
}

