@DynamicSerialize
public abstract class RegistryEvent extends Event {

    private static final long serialVersionUID = 987676907;

    public enum Action {
        UPDATE, DELETE, INSERT
    }

    /**
     * Default Constructor.
     */
    public RegistryEvent() {
        this.setExternal(true);
    }

    /**
     * Initialization Constructor.
     * 
     * @param id
     * @param lid
     * @param objectType
     * @param action
     */
    public RegistryEvent(String id, String lid, String objectType, String username, Action action) {
        super(id);
        this.lid = lid;
        this.objectType = objectType;
        this.username = username;
        this.action = action;
        this.external = true;
    }

    @DynamicSerializeElement
    private String lid;

    @DynamicSerializeElement
    private String objectType;

    @DynamicSerializeElement
    private Action action;

    @DynamicSerializeElement
    private String username;

    public void setObjectType(String objectType) {
        this.objectType = objectType;
    }

    public String getObjectType() {
        return objectType;
    }

    public String getLid() {
        return lid;
    }

    public void setLid(String lid) {
        this.lid = lid;
    }

    @Override
    public String toString() {
        return "Registry Event: " + super.toString() + " Lid: " + lid
                + " Action: " + action + " objectType: " + objectType;
    }

    public Action getAction() {
        return action;
    }

    public void setAction(Action action) {
        this.action = action;
    }

    public String getUsername() {
        return username;
    }

    public void setUsername(String username) {
        this.username = username;
    }

}

