            int indexval = dpBiasChangeMap.get(rid);
            if ("YES"
                    .equalsIgnoreCase(dpManEditButtonArray[indexval].getText())) {
                daaRadarResult.setEditBias("y");
                daaRadarResult.setMemSpanUsed((double) memspan);
            } else {
                daaRadarResult.setEditBias("n");
            }
            daaRadarResult
