    public void clearProductTable() {
        synchronized (productKeySet) {
            productKeySet.clear();
            tableDataArray.clear();
            prodSelTable.removeAll();

            prodSelIdxArray = new boolean[0];

            updateLoadButtonAndProductLabels();
        }
    }

