                _writer.println(this.calculator._codes[i].pluginURL);
            } else {
                _writer.println("no plugin");
            }
            if (this.calculator._codes[i].command != null) {
                _writer.println(this.calculator._codes[i].command);
            } else {
                _writer.println("no command");
            }
        }

