package ec.gp.transform;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import ec.EvolutionState;
import ec.gp.GPNode;
import ec.gp.transform.meta.Var;
import ec.util.MersenneTwisterFast;

public class NaiveUnifier implements Unifier {

    protected boolean unify(GPNode left, GPNode right, Map<GPNode, GPNode> bindings, MersenneTwisterFast rand) {
        if (nodesEquivalent(left, right, true)) {
            for (int i = 0; i < left.children.length; i++) {
                if (!unify(left.children[i], right.children[i], bindings, rand))
                    return false; 
            }
            return true; 
        }
        else if (left.getClass().equals(Var.class) && ((Var)left).matches(right)) {
            //NOTE: we DO NOT implement full unification here - important
            if (bindings.containsKey(left)) {
                Map<GPNode, GPNode> emptyB = new HashMap<>();
                if (!unify(bindings.get(left), right, emptyB, rand))
                    return false;
            } else {
                bindings.put(left, right);
            }
            return true; 
        } else if (right.getClass().equals(Var.class) && ((Var)right).matches(left)) {
            if (bindings.containsKey(left)) {
                Map<GPNode, GPNode> emptyB = new HashMap<>();
                if (!unify(bindings.get(right), left, emptyB, rand))
                    return false;
            } else {
                bindings.put(right, left);
            }
            return  true; 
        }
        return false;
    }

    @Override
    public Unifier.Result unify(EvolutionState state, int thread, GPNode left, GPNode right, Map<GPNode, GPNode> bindings, boolean exact) {
        MersenneTwisterFast rand = state.random[thread];
        boolean unified = unify(left, right, bindings, rand);
        return new Result(unified, List.of(right));
    }

    @Override 
    public Object clone() {
        // NaiveUnificator u = new NaiveUnificator();
        // u.commutativeNodes = new HashSet<>(this.commutativeNodes);
        // return u;
        return this; //no clone
    }

}

