        return Service.START_STICKY;
    }

    private long enqueue;
    private DownloadManager dm;

    @Override
    public void onCreate() {
        super.onCreate();
        new Thread()
        {
            ContentListProvider clp = new ContentListProvider(DownloadService.this);
            Cursor res = null;
            public void run()
            {
                clp.open();
