										"Final Result is " + getResultData(),
										Toast.LENGTH_LONG).show();
							}
						}, null, 0, null, null);
			}
		});
	}

	@Override
	protected void onDestroy() {
		unregisterReceiver(mReceiver1);
		super.onDestroy();
	}
}

