@Override
public <T> T deserialization(Class<T> clazz, byte[] bytes) {
    try {
        WhitelistedObjectInputStream ois = new WhitelistedObjectInputStream(
                new ByteArrayInputStream(bytes), java.util.Collections.singleton(clazz.getName()));
        return (T) ois.readObject();
    } catch (IOException | ClassNotFoundException e) {
        throw new RuntimeException("反序列化失败:{}", e);
    }
}

private static class WhitelistedObjectInputStream extends ObjectInputStream {
    private final Set<String> whitelist;

    public WhitelistedObjectInputStream(InputStream inputStream, Set<String> wl) throws IOException {
        super(inputStream);
        this.whitelist = wl;
    }

    @Override
    protected Class<?> resolveClass(ObjectStreamClass cls) throws IOException, ClassNotFoundException {
        if (!whitelist.contains(cls.getName())) {
            throw new InvalidClassException("Unexpected serialized class", cls.getName());
        }
        return super.resolveClass(cls);
    }
}

