public synchronized Edge createEdge(int id1 , int id2){
    String edgeKey = Edge.getKey(id1, id2);
    Edge e = edgeMap.get(edgeKey);
    if (e == null){
        e = new Edge();
        e.connect(id1, id2);
        edgeMap.put(edgeKey,e);
        getNode(id1).addEdge(e);
        getNode(id2).addEdge(e);
    }
    return e;
}

