                    mMainObj = c.newInstance(AtFairyImpl.this);
                    method = cls.getMethod(GAME_TASK_MAINFUNC);
                    dispatchCompatEvent(OnCompatFiaryEvent.TYPE_NEW_TASK_START1);
                    method.invoke(mMainObj);
                    LtLog.d("auto", " Loop start: print3");
