        calInput.set(yearInt, month, day, 0, 0, 0);
        calToday.getTime();

        long xmilsecsToday = calToday.getTimeInMillis();
        long xmilsecsInput = calInput.getTimeInMillis();
        long xdiffValidityCheck = xmilsecsToday - xmilsecsInput;

        if (xdiffValidityCheck <= 0) {
