        Date dateInput = calInput.getTime();
        Date dateToday = calToday.getTime();
        long star[] = differenceBetweenDates(dateInput, dateToday);
        String grammar[] = croatianGrammar(star);

        int timeLeft = (int) star[2] % 10;
