     * Wake up command
     */
    public static class WakeUpCommand extends SetCommand {
        Property<Status> status = new Property<>(Status.class, PROPERTY_STATUS);

        /**
         * Wake up command
         */
        public WakeUpCommand() {
            super(IDENTIFIER);

            addProperty(status.addValueComponent(new Bytes("00")));
            createBytes();
        }

        WakeUpCommand(byte[] bytes) throws PropertyParseException {
            super(bytes);
            while (propertyIterator.hasNext()) {
                propertyIterator.parseNextSetter(p -> {
                    if (p.getPropertyIdentifier() == PROPERTY_STATUS) return status.update(p);

                    return null;
                });
