            if ((status.getValue() == null || status.getValueComponent().getValueBytes().equals("00") == false)) {
                throw new PropertyParseException(mandatoryPropertyErrorMessage(getClass()));
            }
        }
    }

    public enum Status implements ByteEnum {
        WAKE_UP((byte) 0x00),
