                        equals = equals(td1.getGenericParameterType(p), td2.getGenericParameterType(p));
                    }
                }
            }
            if (!equals) {
                IMetaType b1 = null == t1.getBaseType() ? t1 : t1.getBaseType();
                IMetaType b2 = null == t2.getBaseType() ? t2 : t2.getBaseType();
                if (b1 != t1 || b2 != t2) {
                    equals = equals(b1, b2);
                }
            }
        }
        return equals;
    }

