public int hashCode() {
	final int prime = 31;
	int result = 1;
	result = prime * result + ((nameID == null) ? 0 : nameID.hashCode());
	long temp;
	temp = Double.doubleToLongBits(price);
	result = prime * result + (int) (temp ^ (temp >>> 32));
	result = prime * result + volume;
	return result;
}

