        if (!(o instanceof TokenizerOptions)) return false;
        TokenizerOptions opts = (TokenizerOptions) o;
        return (this.caseInsensitive == opts.caseInsensitive &&
                this.useStopWords == opts.useStopWords &&
                this.useStem == opts.useStem);
    }
}

