     * @return The state hash, or {@code null} if the JWS algorithm is not
     * supported.
     */
    public static StateHash compute(State state, JWSAlgorithm alg) {

        String value = computeValue(state, alg);

        if (value == null) {
            return null;
        }

        return new StateHash(value);
    }


