            loSegs.add(seg);
        }
        String[] sSegs = loSegs.toArray(new String[loSegs.size()]);
        String retValue = StringHelper.implode(sSegs, SEGMENT_SPLIT_STRING);
        if (!retValue.endsWith(SEGMENT_SPLIT_STRING)){
            retValue = retValue + SEGMENT_SPLIT_STRING;
