        String[] segmentStrings = data.split(SEGMENT_SPLIT_STRING); // HL7 breaker

        for(String segmentString : segmentStrings) {
            HL7Segment segment = new HL7Segment(this);
            segment.unmarshal(segmentString);
            getSegments().add(segment);
        }

