	 */
	public int getGroupColumnIndex()
	{
		return groupColumnIndex;
	}

	public void setGroupColumnIndex(int groupColumnIndex)
	{
		this.groupColumnIndex = groupColumnIndex;
	}

	public int getLevel()
	{
		return level;
	}

	public void setLevel(int level)
	{
		this.level = level;
	}

