private int calculateDelay() {
    int delayMs = 0;
    if (maxProcessorDelayMs != 0) {
        long range = (long) maxProcessorDelayMs - minProcessorDelayMs + 1;
        if (range <= 0 || range > Integer.MAX_VALUE) {
            throw new IllegalStateException("Invalid processor delay range: " +
                    "minProcessorDelayMs = " + minProcessorDelayMs +
                    " maxProcessorDelayMs = " + maxProcessorDelayMs);
