    Random random = new Random();
    long range = (long) end - start + 1;
    if (range <= 0 || range > Integer.MAX_VALUE) {
        throw new IllegalArgumentException("Invalid range");
    }
    int randomInt = random.nextInt((int) range) + start;
    return randomInt;
}

