public static int nextInt(int min, int max, Random rand)
{
	if (min > max)
	{
		throw new IllegalArgumentException("min must be <= max");
	}

	int range = (max + 1) - min;
	if (range < 0)
	{
		throw new IllegalArgumentException("range overflow");
	}

	int value = rand.nextInt(range);

	return Math.addExact(value, min);
}

