    public COSDictionary cosSetPieceInfo(COSDictionary dict) {
        if (dict != null) {
            dict.beIndirect();
        }
        return cosSetField(DK_PieceInfo, dict).asDictionary();
    }

    @Override
    public void invalidateCaches() {
        super.invalidateCaches();
        cachedContent = null;
        cachedTransformedBBox = null;
    }

    /*
     * (non-Javadoc)
