package net.gminerz.bungeecore.motd;

import net.md_5.bungee.api.ChatColor;

public class MOTDManager {

    private static MOTDManager motdManager;
    private boolean custom;
    private String up, down;

    public MOTDManager() {
        this.up = ChatColor.RED + "ERROR! PLEASE REPORT!";
        this.down = ChatColor.RED + "ERROR! PLEASE REPORT!";
    }

    public void setCustom(boolean custom) {
        this.custom = custom;
    }

    public boolean isCustom() {
        return custom;
    }

    public void setUp(String up) {
        this.up = up;
        this.custom = true;
    }

    public String getUp() {
        return up;
    }

    public void setDown(String down) {
        this.down = down;
        this.custom = true;
    }

    public String getDown() {
        return down;
    }

    public String getMOTD() {
        if (!custom) {
            return ChatColor.GOLD + ChatColor.BOLD.toString() + "GMINERZ" + ChatColor.DARK_GRAY + ChatColor.BOLD.toString() + " >> " + ChatColor.GREEN + "Click to connect!\n" + ChatColor.AQUA + "Follow us on twitter for updates " + ChatColor.BOLD.toString() + "@GMinerz.";
        } else {
            return ChatColor.GOLD + ChatColor.BOLD.toString() + "GMINERZ" + ChatColor.DARK_GRAY + ChatColor.BOLD.toString() + " >> " + ChatColor.YELLOW + up + "\n" + ChatColor.AQUA + down;
        }
    }

    public static MOTDManager getInstance() {
        if (motdManager == null) motdManager = new MOTDManager();
        return motdManager;
    }
}

