import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;

/**
 * Class to convert primitive classes to their corresponding Objects.
 */
public class Primitives {

	private static Map<Class<?>, Class<?>> classMap;

	/**
	 * Converts type argument to its Object representation if it's 
	 * a primitive class, otherwise the argument itself is returned.
	 * 
	 * @param type the primitive class type
	 * @return Object class representation of the given primitive type or the argument itself
	 */
	static Type convertToObject(Type type) {
		if (type != null && type instanceof Class && ((Class<?>) type).isPrimitive()) {
			Class<?> objClass = getClassMap().get((Class<?>) type);
			return (objClass == null) ? (Class<?>) type : objClass;
		}
		return type;
	}

	private static Map<Class<?>, Class<?>> getClassMap() {
		if (classMap == null) {
			classMap = new HashMap<Class<?>, Class<?>>();
			classMap.put(boolean.class, Boolean.class);
			classMap.put(byte.class, Byte.class);
			classMap.put(char.class, Character.class);
			classMap.put(float.class, Float.class);
			classMap.put(int.class, Integer.class);
			classMap.put(long.class, Long.class);
			classMap.put(short.class, Short.class);
			classMap.put(double.class, Double.class);
		}
		return classMap;
	}
}

