    public StudentSearchFragment() {
    }

    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        View view = inflater.inflate(R.layout.student_search, container, false);
        FirebaseDatabase firebaseDatabase = FirebaseDatabase.getInstance();
        mDatabaseReference = firebaseDatabase.getReference();
        mFirebaseHelper = FirebaseHelper.getInstance(mDatabaseReference, getActivity());
        mSearch_et = (EditText) view.findViewById(R.id.studentSearch_editText);
        mSearch_et.requestFocus();
        BounceView.addAnimTo(mSearch_et);
        mImageView = (CircleImageView) view.findViewById(R.id.studentSearch_image);
        mFname_tv = (TextView) view.findViewById(R.id.studentSearch_fname_textView);
        mCourse_tv = (TextView) view.findViewById(R.id.studentSearch_course_textView);
        mYear_tv = (TextView) view.findViewById(R.id.studentSearch_year_textView);
        mDob_tv = (TextView) view.findViewById(R.id.studentSearch_dob_textView);
        mAddress_tv = (TextView) view.findViewById(R.id.studentSearch_address_textView);
        mContact_tv = (TextView) view.findViewById(R.id.studentSearch_contact_textView);
        mSearch_remove_btn = (Button) view.findViewById(R.id.student_search_removeBtn);
        mProgressbar = (ProgressBar) view.findViewById(R.id.studentSearch_progressBar);
        mProgressbar.setProgress(0);
        mProgressbar.setIndeterminate(false);
        mSearch_remove_btn.setEnabled(false);
        mSearch_remove_btn.setTextColor(Color.GRAY);
        ImageView mSearch_imageView = (ImageView) view.findViewById(R.id.studentSearch_search_imageView);

        mSearch_remove_btn.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (SystemClock.elapsedRealtime() - mLastClickTime < 1000) {
                    return;
                }
                mLastClickTime = SystemClock.elapsedRealtime();
                mProgressbar.setIndeterminate(true);
                mSearch_remove_btn.setEnabled(false);
                final String student_uid = mSearch_et.getText().toString().trim();
                if (student_uid.equals("")) {
                    Log.d(COMMON_TAG, TAG + " mSearch_remove_btn: string student uid is empty");
                    return;
                }
                mDatabaseReference.child("UNIQUE_ID").child(student_uid).removeValue();
                mDatabaseReference.child("User").child(student_uid).removeValue().addOnFailureListener(new OnFailureListener() {
                    @Override
                    public void onFailure(@NonNull Exception e) {
                        mSearch_et.setText("");
                        mSearch_et.setError("There's something wrong in the database, please report to the administrator immediately");
                        Log.e(COMMON_TAG, TAG + " removeValue: " + e.getMessage());
                        mProgressbar.setIndeterminate(false);
                        mProgressbar.setProgress(0);
                        mSearch_remove_btn.setTextColor(Color.DKGRAY);
                        mSearch_remove_btn.setEnabled(false);
                    }
                }).addOnSuccessListener(new OnSuccessListener<Void>() {
                    @Override
                    public void onSuccess(Void aVoid) {
                        Fragment newFragment = new HomeFragment();
                        FragmentTransaction transaction = getFragmentManager().beginTransaction();
                        transaction.replace(R.id.fragment_container, newFragment);
                        transaction.commit();
                        Log.d(COMMON_TAG, TAG + " Student successfully remove");
                        mProgressbar.setIndeterminate(false);
                        mProgressbar.setProgress(0);
                        mSearch_remove_btn.setTextColor(Color.DKGRAY);
                        mSearch_remove_btn.setEnabled(true);
                    }
                });
            }
        });

        mSearch_imageView.setOnClickListener(new View.OnClickListener() {
            @Override
            public void onClick(View v) {
                if (SystemClock.elapsedRealtime() - mLastClickTime < 1000) {
                    return;
                }
                mLastClickTime = SystemClock.elapsedRealtime();
                mProgressbar.setIndeterminate(true);
                mSearch_remove_btn.setEnabled(false);
                String student_uid = mSearch_et.getText().toString().trim();
                if (student_uid.equals("")) {
                    mSearch_et.setError("Don't leave this field empty");
                    mSearch_et.requestFocus();
                    mSearch_remove_btn.setEnabled(false);
                    mProgressbar.setIndeterminate(false);
                    mProgressbar.setProgress(0);
                    return;
                }
                mProgressbar.setIndeterminate(true);
                mFirebaseHelper.searchStudent(student_uid, mImageView, mFname_tv, mCourse_tv,
                        mYear_tv, mDob_tv, mAddress_tv, mContact_tv);

                mSearch_remove_btn.setTextColor(Color.DKGRAY);
                mSearch_remove_btn.setEnabled(true);
                try {
                    new Handler().postDelayed(new Runnable() {
                        @Override
                        public void run() {
                            mProgressbar.setIndeterminate(false);
                        }
                    }, 1200);
                } catch (Exception e) {
                    e.printStackTrace();
                }

            }
        });
        BounceView.addAnimTo(mSearch_remove_btn);
        return view;
    }


    @Override
    public void onDetach() {
        super.onDetach();
        Objects.requireNonNull(getFragmentManager()).beginTransaction().remove(new StudentSearchFragment()).commit();
    }

    @Override
    public void onDestroy() {
        super.onDestroy();
    }
}

package com.likefool.apps.aliketweetr.activities;

import android.content.Intent;
import android.os.Bundle;
import android.support.v4.widget.SwipeRefreshLayout;
import android.support.v7.app.ActionBarActivity;
import android.util.Log;
import android.view.Menu;
import android.view.MenuItem;
import android.widget.ListView;
import android.widget.Toast;

import com.activeandroid.query.Select;
import com.likefool.apps.aliketweetr.R;
import com.likefool.apps.aliketweetr.RestApplication;
import com.likefool.apps.aliketweetr.adapters.TweetsArrayAdapter;
import com.likefool.apps.aliketweetr.helpers.EndlessScrollListener;
import com.likefool.apps.aliketweetr.helpers.RestClient;
import com.likefool.apps.aliketweetr.models.Tweet;
import com.loopj.android.http.JsonHttpResponseHandler;

import org.apache.http.Header;
import org.json.JSONArray;
import org.json.JSONObject;

import java.util.ArrayList;
import java.util.List;

public class TimelineActivity extends ActionBarActivity {

    private RestClient client;
    private ArrayList<Tweet> tweets;
    private TweetsArrayAdapter tweetAdapter;
    private ListView lvTweets;
    private SwipeRefreshLayout swipeContainer;


    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(R.layout.activity_timeline);

        lvTweets = (ListView) findViewById(R.id.lvTweets);
        tweets = new ArrayList<>();
        tweetAdapter = new TweetsArrayAdapter(this, tweets);
        lvTweets.setAdapter(tweetAdapter);
        client = RestApplication.getRestClient(); // singleton client
        tweetAdapter.clear();
        populateTimeline(1);
        lvTweets.setOnScrollListener(new EndlessScrollListener() {
            @Override
            public void onLoadMore(int page, int totalItemsCount) {
                populateTimeline(page);
            }
        });

        swipeContainer = (SwipeRefreshLayout) findViewById(R.id.swipeContainer);
        // Setup refresh listener which triggers new data loading
        swipeContainer.setOnRefreshListener(new SwipeRefreshLayout.OnRefreshListener() {
            @Override
            public void onRefresh() {
                // Your code to refresh the list here.
                // Make sure you call swipeContainer.setRefreshing(false)
                // once the network request has completed successfully.
                tweetAdapter.clear();
                populateTimeline(1);
            }
        });
        // Configure the refreshing colors
        swipeContainer.setColorSchemeResources(android.R.color.holo_blue_bright,
                android.R.color.holo_green_light,
                android.R.color.holo_orange_light,
                android.R.color.holo_red_light);

    }

    private void populateTimeline(int i) {
        client.getHomeTimeline(i, new JsonHttpResponseHandler() {
            // Success
            @Override
            public void onSuccess(int statusCode, Header[] headers, JSONArray json) {
                tweetAdapter.addAll(Tweet.fromJSONArray(json));
                // Now we call setRefreshing(false) to signal refresh has finished
                swipeContainer.setRefreshing(false);
            }

            @Override
            public void onFailure(int statusCode, Header[] headers, Throwable throwable, JSONObject response) {
                if (response != null) {
                    Log.e("ERROR", "populateTimeline fail, response: " + response.toString());
                }
                Toast.makeText(getApplicationContext(), "Timeline Fail", Toast.LENGTH_SHORT).show();

                // Query ActiveAndroid for list of data
                List<Tweet> localTweets = new Select().from(Tweet.class)
                        .orderBy("CreatedAt DESC").limit(100).execute();
                tweetAdapter.addAll(localTweets);

                swipeContainer.setRefreshing(false);

            }


        });
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        // Inflate the menu; this adds items to the action bar if it is present.
        getMenuInflater().inflate(R.menu.menu_timeline, menu);
        return true;
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        // Handle action bar item clicks here. The action bar will
        // automatically handle clicks on the Home/Up button, so long
        // as you specify a parent activity in AndroidManifest.xml.
        int id = item.getItemId();

        //noinspection SimplifiableIfStatement
        if (id == R.id.twitter_post) {
            goPost();
            return true;
        }

        return super.onOptionsItemSelected(item);
    }

    private void goPost() {
        Intent i = new Intent(this, PostActivity.class);
        startActivityForResult(i, 3458);
    }

    @Override
    protected void onActivityResult(int requestCode, int resultCode, Intent data) {
        if(resultCode == RESULT_OK){
            tweetAdapter.clear();
            populateTimeline(1);
        }
    }
}

package com.genie.simplerss.classes;

import android.content.Context;
import android.content.Intent;
import android.graphics.Bitmap;
import android.graphics.Point;
import android.os.Bundle;
import android.support.v4.app.NavUtils;
import android.support.v7.app.ActionBar;
import android.support.v7.app.ActionBarActivity;
import android.util.Log;
import android.view.Menu;
import android.view.MenuItem;
import android.view.View;
import android.view.ViewGroup;
import android.widget.ArrayAdapter;

import com.androidquery.AQuery;
import com.androidquery.callback.AjaxStatus;
import com.androidquery.util.AQUtility;
import com.androidquery.util.XmlDom;
import com.genie.simplerss.R;

import java.util.List;

/**
 * Base activity with implementation httpAsyncCallback and cleanCacheAsync
 */
abstract public class BaseActivity extends ActionBarActivity {
    public static final String TAG = "BaseActivity";

    // AQuery and UI variables
    protected AQuery aq; // Common AQuery object for root view
    protected AQuery mIAq; // Common AQuery object for personalized UI objects (views) etc.

    // ActionBar variables
    protected boolean showLogo = false;
    protected boolean showHomeUp = true;
    protected boolean showTitle = false;
    protected boolean showOptions = false;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        setContentView(getContainer());

        // Set defaults for layout
        aq = new AQuery(this);
        mIAq = new AQuery(this);

        // Set up the action bar
        final ActionBar actionBar = getSupportActionBar();
        actionBar.setDisplayHomeAsUpEnabled(showHomeUp);
        actionBar.setDisplayUseLogoEnabled(showLogo);
        actionBar.setDisplayShowTitleEnabled(showTitle);
        actionBar.setNavigationMode(ActionBar.NAVIGATION_MODE_STANDARD);
    }

    @Override
    protected void onStart() {
        super.onStart();
    }

    @Override
    protected void onResume() {
        super.onResume();
    }

    @Override
    protected void onPause() {
        super.onPause();
    }

    @Override
    protected void onStop() {
        super.onStop();
    }

    @Override
    protected void onDestroy() {
        super.onDestroy();

        // Clean the file cache with advance option
        if (isTaskRoot()) {
            // Starts cleaning when cache size is larger than AQ_DISK_CACHE_MAX_LIMIT and remove the least recently used
            // files until cache size is less than AQ_DISK_CACHE_MIN_LIMIT
            AQUtility.cleanCacheAsync(this, Constants.AQ_DISK_CACHE_MAX_LIMIT,
                    Constants.AQ_DISK_CACHE_MIN_LIMIT);

            // Disable all ajax calls
            aq.ajaxCancel();
        }
    }

    @Override
    public boolean onCreateOptionsMenu(Menu menu) {
        // Inflate the menu; this adds items to the action bar if it is present.
        if (showOptions) {
            getMenuInflater().inflate(R.menu.main, menu);

            // Enable this if you want display search widget
//            SearchManager searchManager = (SearchManager) getSystemService(Context.SEARCH_SERVICE);
//            SearchView searchView = (SearchView) menu.findItem(R.id.menu_search).getActionView();
//            searchView.setSearchableInfo(searchManager.getSearchableInfo(getComponentName()));
            return true;
        } else {
            return super.onCreateOptionsMenu(menu);
        }
    }

    @Override
    public boolean onPrepareOptionsMenu(Menu menu) {
        return super.onPrepareOptionsMenu(menu);
    }

    @Override
    public boolean onOptionsItemSelected(MenuItem item) {
        switch (item.getItemId()) {
            case android.R.id.home:
                NavUtils.navigateUpFromSameTask(this);
                return true;
            default:
                return super.onOptionsItemSelected(item);
        }
    }

    @Override
    public void onActivityResult(int requestCode, int resultCode, Intent intent) {
        if (requestCode == 0) {
            if (resultCode == RESULT_OK) {
                if (Constants.ENABLE_DEBUG) {
                    Log.i(TAG, "onActivityResult: ok");
                }
            } else if (resultCode == RESULT_FIRST_USER) {
                if (Constants.ENABLE_DEBUG) {
                    Log.i(TAG, "onActivityResult: user");
                }
            } else if (resultCode == RESULT_CANCELED) {
                if (Constants.ENABLE_DEBUG) {
                    Log.i(TAG, "onActivityResult: canceled");
                }
            }
        }
    }

    /**
     * Returns current content view
     *
     * @return R.layout
     */
    abstract protected int getContainer();

    /**
     * Obtain data from server
     *
     * @param url    Requested url
     * @param xml    Response data
     * @param status Current request status
     */
    public void httpAsyncCallback(String url, XmlDom xml, AjaxStatus status) {
        // JSON processing
        if (xml != null) { // Successful ajax call
            if (Constants.ENABLE_DEBUG) {
                //                Log.i(TAG, "Response: " + xml.toString());
            }

            processData(url, xml);
        } else { // Error for http response code that's not 200-299, 422 for current application
            if (status.getCode() == AjaxStatus.NETWORK_ERROR) {
                if (Constants.ENABLE_DEBUG) {
                    Log.i(TAG, "Network error");
                }

                Tools.showToast(this, this.getString(R.string.msg_connect_error));
            } else if (status.getError() != null) {
                if (Constants.ENABLE_DEBUG) {
                    Log.i(TAG, "Error: " + status.getError());
                }

                String errorString = String.format(this.getString(R.string.error),
                        status.getCode(), status.getError());
                Tools.showToast(this, errorString);
            } else {
                if (Constants.ENABLE_DEBUG) {
                    Log.i(TAG, "Error: server response is empty or server is silent");
                }

                Tools.showToast(this, this.getString(R.string.msg_server_error)); // Server didn't answered
            }

            processError(url, status);
        }
    }

    /**
     * Requests data for current activity
     */
    abstract protected void httpAsyncRequest();

    /**
     * Request image icon and set this to view
     *
     * @param resId        Icon holder Id
     * @param thumbnailUrl Image url
     */
    protected void imageAsyncRequest(int resId, String thumbnailUrl) {
        Bitmap preset = mIAq.getCachedImage(thumbnailUrl);
        if (preset != null) {
            mIAq.id(resId).image(preset, AQuery.RATIO_PRESERVE);
        } else {
            Point size = new Point();
            getWindowManager().getDefaultDisplay().getSize(size);
            final int width = size.x;

            // Use AQuery.RATIO_PRESERVE if want to use flexible layout like wrap_content for images
            mIAq.id(resId).image(thumbnailUrl, Constants.ENABLE_MEMORY_CACHE,
                    Constants.ENABLE_DISK_CACHE, width, R.drawable.network_error, null,
                    AQuery.FADE_IN, AQuery.RATIO_PRESERVE);
        }
    }

    protected void imageRequest(int resId, int placeholderId) {
        mIAq.id(resId).image(placeholderId);
    }

    /**
     * Process data from server
     *
     * @param url Requested url
     * @param xml Response data
     * @return Processing status: TRUE if handle and FALSE otherwise
     */
    abstract protected void processData(String url, XmlDom xml);

    abstract protected void processError(String url, AjaxStatus status);

    /**
     * Custom ArrayAdapter throws JSONException etc.
     *
     * @author CoMRaDe
     */
    abstract public class CatalogAdapter extends ArrayAdapter<XmlDom> {
        private final int mViewItem;

        public CatalogAdapter(Context context, int textViewResourceId, List<XmlDom> objects) {
            super(context, textViewResourceId, objects);

            mViewItem = textViewResourceId;
        }

        public void addAll(List<XmlDom> items) {
            for (XmlDom item : items) {
                add(item);
            }
        }

        @Override
        public View getView(int position, View convertView, ViewGroup parent) {
            if (convertView == null) {
                convertView = getLayoutInflater().inflate(mViewItem, null);
            }

            // Prepare internal views and catch JSON errors
            prepareView(position, convertView, parent);

            return convertView;
        }

        /**
         * Prepares internal views in convertView
         *
         * @param position
         * @param convertView
         */
        abstract public void prepareView(int position, View convertView, ViewGroup parent);
    }
}

