enum LifecycleEvent {
    CREATE,
    DESTROY,
    ;

    public static LifecycleEvent corresponding(LifecycleEvent event) {
        switch(event) {
            case CREATE: return DESTROY;
            case DESTROY: return CREATE;
        }
        return null;
    }
}

