package me.doggy.app.ui.main.fragments;

import android.content.Context;
import android.content.Intent;
import android.graphics.Bitmap;
import android.graphics.drawable.BitmapDrawable;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.ImageButton;
import android.widget.Toast;

import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import androidx.annotation.RequiresApi;

import me.doggy.app.R;
import me.doggy.app.net.CustomClient;
import me.doggy.app.net.MessageHeader;
import me.doggy.app.net.Utils;
import me.doggy.app.ui.main.activities.ImageShower;

public class FilterRepeaterFragment extends PageFragment {

    public FilterRepeaterFragment() {
        super(R.layout.fragment_filter_repeater);
    }

    private static final int IMAGE_FROM_EXAMPLE_CODE = 1000;
    private static final int IMAGE_TO_EXAMPLE_CODE = 1001;
    private static final int IMAGE_FROM_CODE = 1002;
    private static final int IMAGE_TO_CODE = 1003;

    private ImageButton _imageFromExample;
    private ImageButton _imageToExample;
    private ImageButton _imageFrom;
    private ImageButton _imageTo;

    private void pickImageFromGallery(int code) {
        Intent intent = new   Intent(Intent.ACTION_PICK, android.provider.MediaStore.Images.Media.EXTERNAL_CONTENT_URI);
        startActivityForResult(intent, code);
    }

    @RequiresApi(api = Build.VERSION_CODES.Q)
    @Nullable
    @Override
    public View onCreateView(@NonNull LayoutInflater inflater, @Nullable ViewGroup container, @Nullable Bundle savedInstanceState) {
        View view = super.onCreateView(inflater, container, savedInstanceState);

        _imageFromExample = view.findViewById(R.id.image);
        _imageToExample = view.findViewById(R.id.imageToExample);
        _imageFrom = view.findViewById(R.id.imageFrom);
        _imageTo = view.findViewById(R.id.imageTo);
        Button repeatBtn = view.findViewById(R.id.restore);
        repeatBtn.setOnClickListener(v -> {
            repeat();
        });

        _imageFromExample.setOnClickListener(v -> {
            pickImageFromGallery(IMAGE_FROM_EXAMPLE_CODE);
        });
        _imageToExample.setOnClickListener(v -> {
            pickImageFromGallery(IMAGE_TO_EXAMPLE_CODE);
        });
        _imageFrom.setOnClickListener(v -> {
            pickImageFromGallery(IMAGE_FROM_CODE);
        });
        _imageTo.setOnClickListener(v -> {
            BitmapDrawable drawable = (BitmapDrawable)_imageTo.getDrawable();
            if(drawable == null) {
                return;
            }
            Bitmap bitmap = drawable.getBitmap();
            if(bitmap != null) {
                Intent imageShower = new Intent(getActivity(), ImageShower.class);
                imageShower.putExtra("image", bitmap);
                startActivity(imageShower);
            }
        });

        Context context = getContext();
        CustomClient client = CustomClient.getInstance();
        client.MessageHeaderReceived.addListener(pair -> {
            MessageHeader header = pair.second;
            if(header.id == CustomClient.MessageType.ImageRepeater.ordinal()) {
                Utils.receiveBitmap(client, bitmap -> {
                    getActivity().runOnUiThread(() -> {
                        _imageTo.setImageBitmap(bitmap);
                        Toast.makeText(context, "got it!", Toast.LENGTH_SHORT);
                    });
                });
            }
        });

        return view;
    }

    @Override
    public void onActivityResult(int requestCode, int resultCode, Intent data) {
        super.onActivityResult(requestCode, resultCode, data);
        if (resultCode == getActivity().RESULT_OK) {
            final Uri imageUri = data.getData();
            switch (requestCode) {
                case IMAGE_FROM_EXAMPLE_CODE:
                    _imageFromExample.setImageURI(imageUri);
                    break;

                case IMAGE_TO_EXAMPLE_CODE:
                    _imageToExample.setImageURI(imageUri);
                    break;

                case IMAGE_FROM_CODE:
                    _imageFrom.setImageURI(imageUri);
                    break;
            }

        }
    }

    private void repeat() {
        if(_imageFromExample.getDrawable() == null || _imageToExample.getDrawable() == null || _imageFrom.getDrawable() == null) {
            Toast.makeText(getContext(), "Some Images are empty", Toast.LENGTH_SHORT).show();
            return;
        }

        Bitmap imageFromExampleBitmap = ((BitmapDrawable)_imageFromExample.getDrawable()).getBitmap();
        Bitmap imageToExampleBitmap = ((BitmapDrawable)_imageToExample.getDrawable()).getBitmap();
        Bitmap imageFromBitmap = ((BitmapDrawable)_imageFrom.getDrawable()).getBitmap();

        if(_imageFromExample.getWidth() != _imageToExample.getWidth() || _imageFromExample.getHeight() != _imageToExample.getHeight()) {
            Toast.makeText(getContext(), "Example images aren't same sizes", Toast.LENGTH_SHORT).show();
            return;
        }

        CustomClient client = CustomClient.getInstance();

        int bodySize = Utils.getImageCountOfBytes(imageFromExampleBitmap) +
                       Utils.getImageCountOfBytes(imageToExampleBitmap) +
                       Utils.getImageCountOfBytes(imageFromBitmap);

        Runnable failed = () -> {
            getActivity().runOnUiThread(() -> {
                Toast.makeText(getContext(), "failed to send", Toast.LENGTH_SHORT).show();
            });
        };
        Runnable success = () -> {
            getActivity().runOnUiThread(() -> {
                Toast.makeText(getContext(), "sent, waiting for result", Toast.LENGTH_SHORT).show();
            });
        };

        Toast.makeText(getContext(), "Sending...", Toast.LENGTH_SHORT).show();
        client.send(new MessageHeader(CustomClient.MessageType.ImageRepeater, bodySize), ()-> {
            Utils.sendImage(client, imageFromExampleBitmap, () -> {
                Utils.sendImage(client, imageToExampleBitmap, () -> {
                    Utils.sendImage(client, imageFromBitmap, success, failed);
                }, failed);
            }, failed);
        }, failed);
    }
}

