				.isOk().expectBody(String.class)
				.value(Matchers.containsString("Address"))
				.value(Matchers.containsString("6085551023"))
				.value(Matchers.containsString("Madison"))
				.value(Matchers.containsString("Max"));
	}

	@TestConfiguration
