					else if (lastName.equals(george.getLastName())) {
						return Lists.newArrayList(george);
					}
					return Lists.emptyList();
				}
				@Override
				public Owner findById(int id) {
					if (id == TEST_OWNER_ID) {
						return george;
					}
					return null;
				}
				@Override
				public void save(Owner owner) {
				}
			};
		}
	}

}

