package org.pixelexperience.thermalcontroller;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.util.Log;
import android.text.TextUtils;

import com.android.internal.util.custom.thermal.ThermalController;

public class Receiver extends BroadcastReceiver {
    private static final String TAG = "ThermalController:Receiver";
    private static final boolean DEBUG = false;

    @Override
    public void onReceive(Context context, Intent intent) {
        if (intent.getAction() != null && intent.getAction().equals(ThermalController.ACTIVE_PACKAGE_CHANGED_ACTION)) {
            if (DEBUG) Log.d(TAG, "Received " + ThermalController.ACTIVE_PACKAGE_CHANGED_ACTION);
            if (intent.getExtras() != null) {
                String packageName = intent.getExtras().getString(ThermalController.ACTIVE_PACKAGE_CHANGED_EXTRA);
                int profile = 0;
                if (packageName != null && !TextUtils.isEmpty(packageName)) {
                    if (DEBUG) Log.d(TAG, "Received " + packageName);
                    profile = Preferences.getProfileId(context, packageName);
                    if (packageName.equals("com.tencent.ig") && profile == ThermalProfiles.MODE_GAME) {
                        profile = ThermalProfiles.MODE_PUBG;
                    }
                }
                ThermalProfiles.writeProfile(profile);
            }
        }
    }
}

