@Slf4j
@RestController
public class Server7AdaptorController {
    @Autowired
    private ServerAdaptor serverAdaptor;

    @PostConstruct
    public void init() {
        try {
            this.serverAdaptor.init("server7");
        } catch (BizException e) {
            log.error("服务端适配器初始化失败！",e);
