private void copyBlockData(InputBlockStream inputBlockStream, OutputStream out)
		throws IOException {

	if (compressed) {
		try (DeflaterOutputStream deflaterOut =
			new DeflaterOutputStream(out, new Deflater(Deflater.BEST_SPEED))) {

			copyBlocks(inputBlockStream, deflaterOut);
			deflaterOut.finish();
		}
	}
	else {
		copyBlocks(inputBlockStream, out);
	}
}

private void copyBlocks(InputBlockStream inputBlockStream, OutputStream out)
		throws IOException {

	int blocksRemaining = getBlockCount();

	BufferFileBlock block;
	while ((block = inputBlockStream.readBlock()) != null) {
		if (blocksRemaining == 0) {
			throw new IOException("unexpected data in stream");
		}
		out.write(block.toBytes());
		--blocksRemaining;
	}
