			logger.log(Severity.FATAL, "Failed while parsing Static XML",ignorableException ) ;
			ignorableException.printStackTrace();
		}

		return 0;
	}

	public boolean isLogOnSuccessful(int response)
	{
		return true ;
	}	

}

