public class TimeIntervalTest {
    public static void main(String[] args) {
//        test1();
        test2();
    }

    private static void test1() {
        TimeInterval timer = DateUtil.timer();

        try {
            TimeUnit.SECONDS.sleep(2);
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
        //---------------------------------
        //-------这是执行过程
        //---------------------------------

        Console.log("花费毫秒数", timer.interval()); // 花费毫秒数
        Console.log("花费分钟数", timer.intervalMinute()); // 花费分钟数
        Console.log("返回花费时间：{}，并重置开始时间", timer.intervalRestart()); // 返回花费时间，并重置开始时间
    }

    private static void test2() {
        final TimeInterval timer = new TimeInterval();

        // 分组1
        timer.start("1");
        ThreadUtil.sleep(800);
        long l = timer.intervalRestart("1");
        Console.log(l);

        // 分组2
        timer.start("2");
        ThreadUtil.sleep(900);

        Console.log("Timer 1 took {} ms", timer.intervalMs("1"));
        Console.log("Timer 2 took {} ms", timer.intervalMs("2"));
        String intervalPretty = timer.intervalPretty();
        Console.log(intervalPretty);
    }
}

