        // TODO
        textFieldValue.setText("56.41");
        textFieldValue.setDisable(true);
        beginDate.setDisable(true);
    }    

    @FXML
    private void update(){
        if(Validate.validateEmpty("Name", textFieldServiceName.getText())){
